def pertence_sem_regex(palavra):
    viu_b=False
    for simbolo in palavra:
        if simbolo=='b': viu_b=True
        elif simbolo=='a':
            if viu_b: return False
        else: return False
    return True
assert all(pertence_sem_regex(s) for s in ['', 'aaa', 'abb'])
assert not pertence_sem_regex('aba') and not pertence_sem_regex('c')
